import type { FirstDayOfWeek, CalendarMode } from './types'

interface BetterDatePickerBaseProps {
  /**
   * When true, displays a condensed calendar view showing only one week
   * instead of the full month
   * @default false
   */
  condensed?: boolean
  /**
   * If true, the input is disabled
   * @default false
   */
  disabled?: boolean
  /**
   * Whether the input is in an error state
   * @default false
   */
  error?: boolean
  /**
   * The error message to display below the input while `error` is true. It is
   * announced to assistive technology as the field's error. Accepts any
   * renderable content, e.g. a FormattedMessage element
   */
  errorMessage?: ReactNode
  /**
   * The day that starts the week in the calendar grid, and that weeks snap
   * to in week mode. Defaults to the locale's first day of the week
   */
  firstDayOfWeek?: FirstDayOfWeek
  /**
   * Descriptive helper text displayed below the input. For error text, use
   * `errorMessage` together with `error` instead. Accepts any renderable
   * content, e.g. a FormattedMessage element
   */
  helperText?: ReactNode
  /**
   * Callback that is called for each visible date. Returning true marks the
   * date as unavailable so it cannot be selected
   */
  isDateUnavailable?: (date: Date) => boolean
  /**
   * The label for the input element. Accepts any renderable content, e.g. a
   * FormattedMessage element
   */
  label: ReactNode
  /**
   * The latest date that a user may select
   */
  maxDate?: Date
  /**
   * The earliest date that a user may select
   */
  minDate?: Date
  /**
   * The name of the input element, used when submitting an HTML form
   */
  name?: string
  /**
   * Whether user input is required before form submission
   * @default false
   */
  required?: boolean
  /**
   * The size of the input
   * @default 'medium'
   */
  size?: TextInputSize
  /**
   * IANA timezone identifier (e.g. 'America/New_York') used to determine
   * today's date and the dates emitted through onChange.
   * Defaults to the user's local timezone if not provided or invalid
   */
  timezone?: string
  /**
   * How validation is surfaced. 'aria' (the default) exposes validity to
   * assistive technology without blocking native form submission; 'native'
   * uses the browser's built-in form validation
   * @default 'aria'
   */
  validationBehavior?: 'aria' | 'native'
  /**
   * The visual style variant of the input field
   * @default 'outlined'
   */
  variant?: TextInputVariant
}

/**
 * State passed to a custom trigger so it can render the current value
 */
export interface BetterDatePickerTriggerState {
  /**
   * The localized, human-readable value, e.g. "Jul 12, 2026" for a day or
   * "Jun 19 – 25, 2026" for a week or range. An empty string when nothing is
   * selected
   */
  displayedText: string
  /**
   * Whether the picker is disabled
   */
  isDisabled: boolean
  /**
   * Whether the calendar popover is currently open
   */
  isOpen: boolean
  /**
   * The selected value in this picker's shape: a Date in day mode, or a
   * [start, end] tuple in week and range modes. null when nothing is selected
   */
  value: Date | [Date, Date] | null
}

/**
 * Props that a custom trigger must spread onto its focusable element so the
 * calendar can open from it, anchor its popover to it, and be announced
 * correctly to assistive technology. `id` and `aria-labelledby` together make
 * the element announce the field label followed by its own text (the value),
 * so render the value as the element's content
 */
export interface BetterDatePickerTriggerProps {
  /**
   * Present only while the picker is in an error state with an errorMessage;
   * points at the rendered error text so it is announced by assistive tech
   */
  'aria-describedby'?: string
  'aria-expanded': boolean
  'aria-haspopup': 'dialog'
  'aria-labelledby': string
  id: string
  onClick: () => void
  ref: React.RefCallback<HTMLElement>
}

/**
 * A custom trigger. Return a single focusable element (e.g. a button) with
 * `triggerProps` spread onto it to anchor the calendar to that element.
 *
 * This is a spread-props contract rather than a react-aria `Pressable` wrapper
 * on purpose. `Pressable` drives presses through pointer events it injects by
 * cloning the child, so the child must forward every DOM prop (including
 * onPointerDown/onPointerUp) to a focusable node. None of this design system's
 * components do that they all forward only a
 * fixed named allow-list — so a Pressable-based slot could not anchor to any
 * component we ship. They do all forward `onClick` and a `ref`, which is
 * exactly what this contract needs, so spreading `triggerProps` works with our
 * own components as well as native elements
 */
export type BetterDatePickerTrigger = (
  state: BetterDatePickerTriggerState,
  triggerProps: BetterDatePickerTriggerProps,
) => ReactElement

export interface BetterDatePickerDayProps extends BetterDatePickerBaseProps {
  /**
   * The initially selected date (uncontrolled)
   */
  defaultValue?: Date | null
  /**
   * How the value reads inside the field trigger. 'segments' renders an
   * editable segmented date input, 'text' renders the localized,
   * human-readable date (e.g. Jul 12, 2026). Only applies when `trigger` is
   * 'field'; the other triggers always render human-readable text
   * @default 'segments'
   */
  displayFormat?: 'segments' | 'text'
  /**
   * Selection mode for the date picker
   * @default 'day'
   */
  mode?: 'day'
  /**
   * Callback invoked with the selected date when it changes, or null when
   * the value is cleared
   */
  onChange?: (date: Date | null) => void
  /**
   * The element the calendar is anchored to. 'field' renders a full input
   * field, 'text' renders the value as a bare text button, 'icon' renders a
   * calendar icon button showing the selected day of the month (or a plain
   * calendar icon while no date is selected), and a function renders a custom
   * element to anchor the calendar to. For every trigger except 'field' the
   * label is still announced to assistive technology
   * @default 'field'
   */
  trigger?: 'field' | 'icon' | 'text' | BetterDatePickerTrigger
  /**
   * The selected date (controlled)
   */
  value?: Date | null
}

export interface BetterDatePickerWeekProps extends BetterDatePickerBaseProps {
  /**
   * The initially selected week (uncontrolled). A single date selects the
   * week containing it
   */
  defaultValue?: Date | [Date, Date] | null
  mode: 'week'
  /**
   * Callback invoked with the start and end dates of the selected week
   */
  onChange?: (range: [Date, Date]) => void
  /**
   * The element the calendar is anchored to. Week selection always renders as
   * localized, human-readable text; 'field' renders it inside an input field,
   * 'text' renders it as a bare text button, and a function renders a custom
   * element to anchor the calendar to
   * @default 'field'
   */
  trigger?: 'field' | 'text' | BetterDatePickerTrigger
  /**
   * The selected week (controlled). A single date selects the week
   * containing it
   */
  value?: Date | [Date, Date] | null
}

export interface BetterDatePickerRangeProps extends BetterDatePickerBaseProps {
  /**
   * Whether a range may span dates marked unavailable by `isDateUnavailable`.
   * When false (the default) the range is clamped so it cannot cross an
   * unavailable date; when true the range may span them and the unavailable
   * dates within it simply stay unselectable
   * @default false
   */
  allowsNonContiguousRanges?: boolean
  /**
   * The initially selected date range (uncontrolled)
   */
  defaultValue?: [Date, Date] | null
  /**
   * How the value reads inside the field trigger. 'segments' renders editable
   * segmented date inputs, 'text' renders the localized, human-readable
   * range. Only applies when `trigger` is 'field'; the other triggers always
   * render human-readable text
   * @default 'segments'
   */
  displayFormat?: 'segments' | 'text'
  mode: 'range'
  /**
   * Callback invoked with the start and end dates of the selected range, or
   * null when the value is cleared
   */
  onChange?: (range: [Date, Date] | null) => void
  /**
   * The element the calendar is anchored to. 'field' renders a full input
   * field, 'text' renders the value as a bare text button, and a function
   * renders a custom element to anchor the calendar to. For every trigger
   * except 'field' the label is still announced to assistive technology
   * @default 'field'
   */
  trigger?: 'field' | 'text' | BetterDatePickerTrigger
  /**
   * The selected date range (controlled)
   */
  value?: [Date, Date] | null
}

export type BetterDatePickerProps =
  | BetterDatePickerDayProps
  | BetterDatePickerRangeProps
  | BetterDatePickerWeekProps

/**
 * The calendar inside the popover, wrapped in a Dialog only when the popover
 * is modal (button and keyboard opens), for its focus trap and accessible
 * name. The segment-opened non-modal popover renders without a Dialog because
 * React Aria's Dialog focuses itself on mount whenever focus is outside it,
 * which would pull focus out of the segments the user just clicked
 */
function CalendarPopoverContent({
  children,
  modal,
}: {
  children: ReactElement
  modal: boolean
}): JSX.Element {
  return modal ? <Dialog className="outline-none">{children}</Dialog> : children
}

function BetterDatePicker(props: BetterDatePickerProps): JSX.Element {
  const {
    condensed = false,
    disabled = false,
    error = false,
    errorMessage,
    firstDayOfWeek: firstDayOfWeekProp,
    helperText,
    isDateUnavailable,
    label,
    maxDate,
    minDate,
    mode = 'day',
    name,
    required = false,
    size = 'medium',
    timezone,
    trigger = 'field',
    validationBehavior = 'aria',
    variant = 'outlined',
  } = props
  // displayFormat only exists for day and range; week always renders as text
  const { displayFormat = 'segments' } = props as {
    displayFormat?: 'segments' | 'text'
  }
  const intl = useIntl()
  const firstDayOfWeek = useFirstDayOfWeek(firstDayOfWeekProp)
  const resolvedTimezone = useMemo(() => resolveTimezone(timezone), [timezone])
  const status: TextInputStatus = disabled
    ? 'disabled'
    : error
    ? 'error'
    : 'default'
  // Segments mode opens the calendar when the segment area is clicked, in
  // addition to the calendar button and the built-in Alt+ArrowDown shortcut.
  // A segment click renders the popover non-modal so focus stays in the
  // segments and typing keeps working while the calendar is visible; the
  // button and keyboard paths keep the default modal popover, which moves
  // focus into the calendar grid
  const [open, setOpen] = useState(false)
  const styles = useFieldStyles(size, status, variant, open)
  const [openedFromSegments, setOpenedFromSegments] = useState(false)
  // Remounts the calendar while the non-modal popover is open so its visible
  // month follows the date being typed into the segments
  const [calendarKey, setCalendarKey] = useState(0)
  const groupRef = useRef<HTMLDivElement>(null)
  const popoverRef = useRef<HTMLDivElement>(null)
  // Tracks deferred state updates so they can be cancelled on unmount,
  // avoiding setState-on-an-unmounted-component warnings
  const deferredTimeouts = useRef<number[]>([])
  const defer = (callback: () => void) => {
    deferredTimeouts.current.push(window.setTimeout(callback, 0))
  }
  useEffect(
    () => () => {
      deferredTimeouts.current.forEach((id) => window.clearTimeout(id))
    },
    [],
  )
  const openFromSegments = (event: React.PointerEvent) => {
    // Ignore right/middle-button releases so a context-menu or secondary
    // press does not pop the calendar open (button > 0 is a secondary button;
    // the primary button, and environments that omit it, report 0). Skip when
    // already open so a stray pointerup cannot flip a modal popover non-modal
    if (disabled || open || event.button > 0) {
      return
    }

    setOpenedFromSegments(true)
    // Deferred so the click event that follows pointerup finishes first;
    // the non-modal popover would otherwise see that click as an outside
    // interaction and immediately close again
    defer(() => setOpen(true))
  }
  const handleOpenChange = (isOpen: boolean) => {
    setOpen(isOpen)

    if (!isOpen) {
      setOpenedFromSegments(false)
    }
  }
  const closeFromSegments = () => {
    setOpen(false)
    setOpenedFromSegments(false)
  }
  // The non-modal popover keeps focus in the segments, which means the
  // popover's own Escape and outside interaction handling never engage, so
  // both are reimplemented here for the segment opened state
  const handleFieldKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === 'Escape' && open && openedFromSegments) {
      closeFromSegments()
    }
  }

  useEffect(() => {
    if (!open || !openedFromSegments) {
      return undefined
    }

    const handlePointerDown = (event: PointerEvent) => {
      const target = event.target as Node

      if (
        groupRef.current?.contains(target) ||
        popoverRef.current?.contains(target)
      ) {
        return
      }

      closeFromSegments()
    }

    document.addEventListener('pointerdown', handlePointerDown, true)

    return () =>
      document.removeEventListener('pointerdown', handlePointerDown, true)
  }, [open, openedFromSegments])

  const syncCalendarToTypedValue = () => {
    if (open && openedFromSegments) {
      // Deferred so the remount samples the picker state after the segment
      // edit that triggered the change has fully settled
      defer(() => setCalendarKey((key) => key + 1))
    }
  }

  const sharedFieldProps = {
    firstDayOfWeek,
    granularity: 'day' as const,
    isDisabled: disabled,
    isInvalid: error || undefined,
    isRequired: required,
    validationBehavior,
    ...calendarConstraints(
      { isDateUnavailable, maxDate, minDate },
      resolvedTimezone,
    ),
  }

  const helperTextElement = helperText ? (
    <Text className={styles.help} slot="description">
      {helperText}
    </Text>
  ) : null

  // FieldError self-shows only while the field is invalid (error === true) and
  // is auto-associated as the field's error message for assistive technology
  const errorElement = errorMessage ? (
    <FieldError className={styles.error}>{errorMessage}</FieldError>
  ) : null

  // The segmented AriaDatePicker field is used only when a field trigger
  // shows editable segments. Every other trigger, the text display format,
  // and week mode render through TextTriggerField
  const useSegmentedField =
    mode !== 'week' && trigger === 'field' && displayFormat === 'segments'

  if (!useSegmentedField) {
    return (
      <TextTriggerField
        {...props}
        condensed={condensed}
        firstDayOfWeek={firstDayOfWeek}
        mode={mode}
        timezone={resolvedTimezone}
        trigger={trigger}
      />
    )
  }

  if (mode === 'range') {
    const {
      allowsNonContiguousRanges,
      defaultValue,
      onChange,
      value,
    } = props as BetterDatePickerRangeProps

    const handleRangeChange = (
      range: { end: DateValue; start: DateValue } | null,
    ) => {
      syncCalendarToTypedValue()
      onChange?.(
        range && [
          toNativeDate(range.start, resolvedTimezone),
          toNativeDate(range.end, resolvedTimezone),
        ],
      )
    }

    return (
      <I18nProvider locale={intl.locale}>
        <AriaDateRangePicker
          {...sharedFieldProps}
          className={baseClasses.container}
          isOpen={open}
          onOpenChange={handleOpenChange}
          {...(allowsNonContiguousRanges && { allowsNonContiguousRanges })}
          {...(name && { endName: `${name}-end`, startName: `${name}-start` })}
          {...(defaultValue !== undefined && {
            defaultValue: defaultValue && {
              end: toCalendarDate(defaultValue[1], resolvedTimezone),
              start: toCalendarDate(defaultValue[0], resolvedTimezone),
            },
          })}
          {...(value !== undefined && {
            value: value && {
              end: toCalendarDate(value[1], resolvedTimezone),
              start: toCalendarDate(value[0], resolvedTimezone),
            },
          })}
          onChange={handleRangeChange}
        >
          <Group
            className={styles.group}
            onKeyDown={handleFieldKeyDown}
            ref={groupRef}
          >
            <Label className={styles.label}>{label}</Label>
            <span className={styles.icon}>
              <DateRangeIcon />
            </span>
            {/* Clicking the segment area is a pointer-only convenience for
                opening the calendar; keyboard users have the calendar button
                and Alt+ArrowDown from the segments. pointerup is used because
                the segments stop propagation of click events */}
            <div
              className="flex items-center flex-1 min-w-0 px-3 overflow-x-auto"
              onPointerUp={openFromSegments}
            >
              <DateInput className="flex" slot="start">
                {(segment) => (
                  <DateSegment className={styles.segment} segment={segment} />
                )}
              </DateInput>
              <span aria-hidden="true" className="px-1 text-sm text-black-60">
                —
              </span>
              <DateInput className="flex" slot="end">
                {(segment) => (
                  <DateSegment className={styles.segment} segment={segment} />
                )}
              </DateInput>
            </div>
            <AriaButton className={styles.button}>
              <span className="w-5">
                <ExpandMore />
              </span>
            </AriaButton>
          </Group>
          {helperTextElement}
          {errorElement}
          <Popover
            contextDriven
            isNonModal={openedFromSegments}
            ref={popoverRef}
          >
            {/* The Dialog wrapper is skipped on the segment-opened path:
                React Aria's Dialog focuses itself on mount whenever focus is
                outside it, which would yank focus out of the segments the
                user just clicked — flashing the field's focus styles off and
                breaking continued typing and the field's Escape handling. The
                button and keyboard paths keep the Dialog for its focus trap
                and accessible name */}
            <CalendarPopoverContent modal={!openedFromSegments}>
              <AriaRangeCalendar
                className={calendarContainerClasses}
                key={calendarKey}
                {...(openedFromSegments && { autoFocus: false })}
              >
                <CalendarHeader condensed={condensed} />
                <CalendarCells
                  condensed={condensed}
                  mode="range"
                  timezone={resolvedTimezone}
                />
              </AriaRangeCalendar>
            </CalendarPopoverContent>
          </Popover>
        </AriaDateRangePicker>
      </I18nProvider>
    )
  }

  const { defaultValue, onChange, value } = props as BetterDatePickerDayProps

  const handleDayChange = (date: DateValue | null) => {
    syncCalendarToTypedValue()
    onChange?.(date && toNativeDate(date, resolvedTimezone))
  }

  return (
    <I18nProvider locale={intl.locale}>
      <AriaDatePicker
        {...sharedFieldProps}
        className={baseClasses.container}
        isOpen={open}
        onOpenChange={handleOpenChange}
        {...(name && { name })}
        {...(defaultValue !== undefined && {
          defaultValue:
            defaultValue && toCalendarDate(defaultValue, resolvedTimezone),
        })}
        {...(value !== undefined && {
          value: value && toCalendarDate(value, resolvedTimezone),
        })}
        onChange={handleDayChange}
      >
        <Group
          className={styles.group}
          onKeyDown={handleFieldKeyDown}
          ref={groupRef}
        >
          <Label className={styles.label}>{label}</Label>
          <span className={styles.icon}>
            <EventIcon />
          </span>
          {/* Clicking the segment area is a pointer-only convenience for
              opening the calendar; keyboard users have the calendar button
              and Alt+ArrowDown from the segments. pointerup is used because
              the segments stop propagation of click events */}
          <div
            className="flex items-center flex-1 min-w-0 px-3"
            onPointerUp={openFromSegments}
          >
            <DateInput className="flex items-center">
              {(segment) => (
                <DateSegment className={styles.segment} segment={segment} />
              )}
            </DateInput>
          </div>
          <AriaButton className={styles.button}>
            <span className="w-5">
              <ExpandMore />
            </span>
          </AriaButton>
        </Group>
        {helperTextElement}
        {errorElement}
        <Popover contextDriven isNonModal={openedFromSegments} ref={popoverRef}>
          {/* See the range picker above for why the Dialog is skipped on the
              segment-opened path */}
          <CalendarPopoverContent modal={!openedFromSegments}>
            <AriaCalendar
              className={calendarContainerClasses}
              key={calendarKey}
              {...(openedFromSegments && { autoFocus: false })}
            >
              <CalendarHeader condensed={condensed} />
              <CalendarCells
                condensed={condensed}
                mode="day"
                timezone={resolvedTimezone}
              />
            </AriaCalendar>
          </CalendarPopoverContent>
        </Popover>
      </AriaDatePicker>
    </I18nProvider>
  )
}

type TextTriggerFieldProps = Pick<
  BetterDatePickerBaseProps,
  | 'condensed'
  | 'disabled'
  | 'error'
  | 'errorMessage'
  | 'helperText'
  | 'isDateUnavailable'
  | 'label'
  | 'maxDate'
  | 'minDate'
  | 'name'
  | 'size'
  | 'variant'
> & {
  allowsNonContiguousRanges?: boolean
  defaultValue?: Date | [Date, Date] | null
  firstDayOfWeek: ReturnType<typeof useFirstDayOfWeek>
  mode: CalendarMode
  onChange?:
    | ((date: Date | null) => void)
    | ((range: [Date, Date]) => void)
    | ((range: [Date, Date] | null) => void)
  timezone: string
  trigger: 'field' | 'icon' | 'text' | BetterDatePickerTrigger
  value?: Date | [Date, Date] | null
}

/**
 * A field-styled trigger button showing the selected value as localized text,
 * with the calendar in a popover. Used for every mode when displayFormat is
 * 'text', and always for week mode since week selection is not natively
 * supported by React Aria's DatePicker
 */
function TextTriggerField({
  allowsNonContiguousRanges,
  condensed = false,
  defaultValue,
  disabled = false,
  error = false,
  errorMessage,
  firstDayOfWeek,
  helperText,
  isDateUnavailable,
  label,
  maxDate,
  minDate,
  mode,
  name,
  onChange,
  size = 'medium',
  timezone,
  trigger,
  value,
  variant = 'outlined',
}: TextTriggerFieldProps): JSX.Element {
  // A function trigger renders a caller supplied element; the string presets
  // map to the built-in anchor treatments ('field' being the full-width
  // field, rendered when anchor is null)
  const customTrigger = typeof trigger === 'function' ? trigger : null
  const anchor: 'icon' | 'text' | null =
    trigger === 'icon' && mode === 'day'
      ? 'icon'
      : trigger === 'icon' || trigger === 'text'
      ? 'text'
      : null
  const intl = useIntl()
  const labelId = useId()
  const valueId = useId()
  const triggerId = useId()
  const helpId = useId()
  const errorId = useId()
  // The error message shows, and is associated, only while error is true
  const showError = error && Boolean(errorMessage)
  const describedBy =
    [helperText ? helpId : null, showError ? errorId : null]
      .filter(Boolean)
      .join(' ') || undefined
  const { formatDateLocal } = useDateFormatters()
  // Serializes a Date as an ISO day read in the configured timezone, so the
  // submitted value matches the day shown rather than the runner's local day
  const isoDate = (date: Date): string => {
    const calendarDate = toCalendarDate(date, timezone)

    return `${calendarDate.year}-${String(calendarDate.month).padStart(
      2,
      '0',
    )}-${String(calendarDate.day).padStart(2, '0')}`
  }
  // A custom trigger renders outside a DialogTrigger, so the popover is
  // controlled and anchored to the caller's element through this ref
  const triggerRef = useRef<HTMLElement | null>(null)
  const setTriggerRef = useCallback((element: HTMLElement | null) => {
    triggerRef.current = element
  }, [])
  const [open, setOpen] = useState(false)
  const wasOpen = useRef(false)
  const status: TextInputStatus = disabled
    ? 'disabled'
    : error
    ? 'error'
    : 'default'
  // Computed here rather than passed from the parent so the field keeps its
  // focused look while this trigger's own popover is open
  const styles = useFieldStyles(size, status, variant, open)
  const [internalValue, setInternalValue] = useState<
    Date | [Date, Date] | null
  >(defaultValue ?? null)

  const controlled = value !== undefined
  const selectedValue: Date | [Date, Date] | null = controlled
    ? value ?? null
    : internalValue

  // Canonical selected week as CalendarDates — the single source for the
  // displayed text, the hidden form value and triggerState in week mode. Uses
  // the same startOfWeek/endOfWeek (locale + firstDayOfWeek) as the calendar's
  // onChange, so what is shown, submitted and emitted always describe the same
  // week rather than being re-derived independently
  const weekRange = (() => {
    if (mode !== 'week') {
      return null
    }

    const weekAnchor = Array.isArray(selectedValue)
      ? selectedValue[0]
      : selectedValue

    if (!weekAnchor) {
      return null
    }

    const anchorDate = toCalendarDate(weekAnchor, timezone)

    return {
      end: endOfWeek(anchorDate, intl.locale, firstDayOfWeek),
      start: startOfWeek(anchorDate, intl.locale, firstDayOfWeek),
    }
  })()

  const displayedValue: Date | [Date, Date] | null =
    mode === 'week'
      ? weekRange && [
          toNativeDate(weekRange.start, timezone),
          toNativeDate(weekRange.end, timezone),
        ]
      : selectedValue

  // The anchor display condenses ranges so the month and year are not
  // repeated when both dates share them, e.g. "Jun 19 – 25, 2026"
  const displayedText = (() => {
    if (!displayedValue) {
      return ''
    }

    // Week text is formatted from the canonical CalendarDates with the
    // configured timezone so it cannot drift by a day from the emitted value
    if (mode === 'week' && weekRange) {
      const start = toNativeDate(weekRange.start, timezone)
      const end = toNativeDate(weekRange.end, timezone)
      const weekFormatter = new Intl.DateTimeFormat(intl.locale, {
        day: 'numeric',
        month: 'short',
        timeZone: timezone,
        year: 'numeric',
      })

      return anchor
        ? weekFormatter.formatRange(start, end)
        : `${weekFormatter.format(start)} — ${weekFormatter.format(end)}`
    }

    // Range and single dates are renormalized to local midnight on their day
    // in the configured timezone so the local-time formatters below cannot
    // drift a day from the calendar highlight and the emitted value
    if (Array.isArray(displayedValue)) {
      const start = toLocalDay(displayedValue[0], timezone)
      const end = toLocalDay(displayedValue[1], timezone)

      return anchor
        ? new Intl.DateTimeFormat(intl.locale, {
            day: 'numeric',
            month: 'short',
            year: 'numeric',
          }).formatRange(start, end)
        : `${formatDateLocal(start)} — ${formatDateLocal(end)}`
    }

    return formatDateLocal(toLocalDay(displayedValue, timezone))
  })()

  const handleChange = (next: Date | [Date, Date]) => {
    if (!controlled) {
      setInternalValue(next)
    }

    setOpen(false)
    ;(onChange as ((value: Date | [Date, Date]) => void) | undefined)?.(next)
  }

  // A custom trigger renders outside a DialogTrigger and the standalone
  // popover has no focus scope, so nothing returns focus to the trigger when
  // the calendar closes. Restore it here on close, matching how a
  // DialogTrigger returns focus to its trigger
  useEffect(() => {
    if (customTrigger && wasOpen.current && !open) {
      triggerRef.current?.focus()
    }

    wasOpen.current = open
  }, [customTrigger, open])

  const triggerState: BetterDatePickerTriggerState = {
    displayedText,
    isDisabled: disabled,
    isOpen: open,
    value: displayedValue,
  }

  // The calendar dialog is identical for every trigger; only the surrounding
  // trigger/popover wiring differs
  const calendar = (
    <Dialog aria-labelledby={labelId} className="outline-none">
      <Calendar
        // eslint-disable-next-line jsx-a11y/no-autofocus
        autoFocus
        condensed={condensed}
        firstDayOfWeek={firstDayOfWeek}
        isDateUnavailable={isDateUnavailable}
        maxDate={maxDate}
        minDate={minDate}
        mode={mode as 'day'}
        onChange={handleChange as (date: Date) => void}
        timezone={timezone}
        value={selectedValue as Date | null}
        {...(allowsNonContiguousRanges && { allowsNonContiguousRanges })}
      />
    </Dialog>
  )

  const footer = (
    <>
      {helperText ? (
        <span className={styles.help} id={helpId}>
          {helperText}
        </span>
      ) : null}
      {showError ? (
        <span className={styles.error} id={errorId}>
          {errorMessage}
        </span>
      ) : null}
      {name && mode === 'day' ? (
        <input
          name={name}
          type="hidden"
          value={
            displayedValue && !Array.isArray(displayedValue)
              ? isoDate(displayedValue)
              : ''
          }
        />
      ) : null}
      {name && mode === 'range' ? (
        <>
          <input
            name={`${name}-start`}
            type="hidden"
            value={
              Array.isArray(displayedValue) ? isoDate(displayedValue[0]) : ''
            }
          />
          <input
            name={`${name}-end`}
            type="hidden"
            value={
              Array.isArray(displayedValue) ? isoDate(displayedValue[1]) : ''
            }
          />
        </>
      ) : null}
      {name && mode === 'week' ? (
        <input
          name={name}
          type="hidden"
          value={
            Array.isArray(displayedValue)
              ? `${isoDate(displayedValue[0])}/${isoDate(displayedValue[1])}`
              : ''
          }
        />
      ) : null}
    </>
  )

  // A custom trigger renders the caller's element and spreads triggerProps
  // onto it. The popover is controlled here (rather than through a
  // DialogTrigger) and anchored to the element via triggerRef; passing
  // triggerRef also excludes the element from the popover's outside-press
  // dismissal, so its onClick can toggle the calendar open and closed
  if (customTrigger) {
    const triggerProps: BetterDatePickerTriggerProps = {
      'aria-expanded': open,
      'aria-haspopup': 'dialog',
      // Self-referencing id so assistive tech announces the field label
      // followed by the element's own text (the displayed value)
      'aria-labelledby': `${labelId} ${triggerId}`,
      id: triggerId,
      ...(describedBy && { 'aria-describedby': describedBy }),
      onClick: () => {
        if (!disabled) {
          setOpen((previous) => !previous)
        }
      },
      ref: setTriggerRef,
    }

    return (
      <I18nProvider locale={intl.locale}>
        <div className="inline-flex flex-col font-sans">
          {/* The calendar dialog is labelled by a hidden copy of the label */}
          <span className="sr-only" id={labelId}>
            {label}
          </span>
          {customTrigger(triggerState, triggerProps)}
          <Popover
            isOpen={open}
            onOpenChange={setOpen}
            placement="bottom start"
            triggerRef={triggerRef}
          >
            {calendar}
          </Popover>
          {footer}
        </div>
      </I18nProvider>
    )
  }

  return (
    <I18nProvider locale={intl.locale}>
      <div
        className={
          anchor ? 'inline-flex flex-col font-sans' : baseClasses.container
        }
      >
        <DialogTrigger isOpen={open} onOpenChange={setOpen}>
          <AriaButton
            aria-labelledby={
              anchor && !displayedText ? labelId : `${labelId} ${valueId}`
            }
            className={
              anchor === 'icon'
                ? 'inline-flex items-center justify-center self-start w-8 h-8 rounded outline-none text-black-90 active:bg-black-10 focus:bg-black-5 focus-visible:ring hover:bg-black-5 disabled:bg-transparent disabled:text-black-30'
                : anchor === 'text'
                ? 'inline-flex items-center gap-1 self-start min-h-8 px-2 text-base font-semibold rounded outline-none text-black-90 active:bg-black-10 focus:bg-black-5 focus-visible:ring hover:bg-black-5 disabled:bg-transparent disabled:text-black-30'
                : clsx(styles.group, 'w-full text-left outline-none')
            }
            isDisabled={disabled}
            {...(describedBy && { 'aria-describedby': describedBy })}
          >
            <span className={anchor ? 'sr-only' : styles.label} id={labelId}>
              {label}
            </span>
            {anchor ? null : (
              <span className={styles.icon}>
                {mode === 'day' ? <EventIcon /> : <DateRangeIcon />}
              </span>
            )}
            <span
              className={
                anchor === 'icon'
                  ? 'sr-only'
                  : anchor === 'text'
                  ? 'truncate'
                  : 'flex-1 min-w-0 px-3 text-sm truncate text-black-90'
              }
              id={valueId}
            >
              {anchor === 'text' && !displayedText ? label : displayedText}
            </span>
            {anchor === 'icon' ? (
              <span className="w-6">
                <CalendarDayIcon
                  day={
                    displayedValue && !Array.isArray(displayedValue)
                      ? toCalendarDate(displayedValue, timezone).day
                      : undefined
                  }
                />
              </span>
            ) : null}
            {anchor === 'text' ? (
              <span aria-hidden="true" className="w-5">
                <ExpandMore />
              </span>
            ) : null}
            {anchor ? null : (
              <span
                className={clsx(styles.button, 'pointer-events-none')}
                role="presentation"
              >
                <span className="w-5">
                  <ExpandMore />
                </span>
              </span>
            )}
          </AriaButton>
          <Popover contextDriven placement="bottom start">
            {calendar}
          </Popover>
        </DialogTrigger>
        {footer}
      </div>
    </I18nProvider>
  )
}

export type { FirstDayOfWeek, CalendarMode }
export default BetterDatePicker
