import {
  fromDate,
  toCalendarDate as toInternalCalendarDate,
} from '@internationalized/date'
import type { CalendarDate, DateValue } from '@internationalized/date'

/**
 * Returns the given IANA timezone when it is valid, falling back to the
 * system timezone otherwise
 */
export function resolveTimezone(timezone?: string): string {
  if (timezone) {
    try {
      Intl.DateTimeFormat(undefined, { timeZone: timezone })

      return timezone
    } catch (e) {
      // Invalid timezone — fall through to the system timezone
    }
  }

  return Intl.DateTimeFormat().resolvedOptions().timeZone
}

/**
 * Converts a native Date into a CalendarDate as read in the given timezone.
 * This is the inverse of toNativeDate, so echoing an onChange value back into
 * the controlled value prop round-trips to the same day rather than drifting.
 */
export function toCalendarDate(date: Date, timezone: string): CalendarDate {
  return toInternalCalendarDate(fromDate(date, timezone))
}

/**
 * Converts a CalendarDate back into a native Date at midnight in the
 * provided timezone
 */
export function toNativeDate(value: DateValue, timezone: string): Date {
  return value.toDate(timezone)
}

/**
 * Renormalizes a Date to local midnight on the calendar day it falls on in
 * the given timezone, so local-time formatters (date-fns, Intl without a
 * timeZone) render the same day the calendar highlights and the form submits
 */
export function toLocalDay(date: Date, timezone: string): Date {
  const calendarDate = toCalendarDate(date, timezone)

  return new Date(calendarDate.year, calendarDate.month - 1, calendarDate.day)
}

export interface CalendarConstraintProps {
  isDateUnavailable?: (date: DateValue) => boolean
  maxValue?: CalendarDate
  minValue?: CalendarDate
}

/**
 * Builds the shared date-constraint props that both the segmented field and the
 * standalone Calendar hand to react-aria: the min/max bounds (converted into
 * the given timezone) and the unavailable-date predicate (wrapped to receive a
 * native Date). Inverted bounds are swapped rather than passed through, because
 * handing react-stately a minValue greater than its maxValue throws the
 * focused-date constraint into a render-phase update loop ("too many
 * re-renders"). Keys are omitted when their source is undefined, so the result
 * is safe to spread directly onto the calendar props.
 */
export function calendarConstraints(
  {
    isDateUnavailable,
    maxDate,
    minDate,
  }: {
    isDateUnavailable?: (date: Date) => boolean
    maxDate?: Date
    minDate?: Date
  },
  timezone: string,
): CalendarConstraintProps {
  const rawMin = minDate ? toCalendarDate(minDate, timezone) : undefined
  const rawMax = maxDate ? toCalendarDate(maxDate, timezone) : undefined
  const inverted = rawMin && rawMax && rawMin.compare(rawMax) > 0
  const minValue = inverted ? rawMax : rawMin
  const maxValue = inverted ? rawMin : rawMax

  return {
    ...(minValue && { minValue }),
    ...(maxValue && { maxValue }),
    ...(isDateUnavailable && {
      isDateUnavailable: (date: DateValue) =>
        isDateUnavailable(toNativeDate(date, timezone)),
    }),
  }
}
