/* eslint-disable react/forbid-component-props */
import type { CalendarDate } from '@internationalized/date'
import { isToday, isWeekend, startOfWeek } from '@internationalized/date'
import clsx from 'clsx'
import React, { useContext, useEffect, useRef, useState } from 'react'
import {
  CalendarCell,
  CalendarGrid,
  CalendarGridBody,
  CalendarGridHeader,
  CalendarHeaderCell,
  CalendarStateContext,
  RangeCalendarStateContext,
} from 'react-aria-components'
import { useIntl } from 'react-intl'
import useDateFormatters from '../hooks/useDateFormatters'
import IconButton from '../IconButton/IconButton'
import ChevronLeft from '../icons/ChevronLeft'
import ChevronRight from '../icons/ChevronRight'
import getStartOfWeek from '../utilities/getStartOfWeek'
import type { CalendarMode, FirstDayOfWeek, SelectedWeek } from './types'

export const calendarContainerClasses =
  'max-w-xs p-6 font-sans rounded bg-white-100 shadow-1'

/**
 * Determines the first day of the week for the calendar. An explicit
 * override always wins, otherwise the legacy behavior is preserved where
 * specific navigator languages (e.g. fr-CA) start the week on Sunday even
 * though the base locale does not. Returning undefined defers to the
 * locale's default
 */
export function useFirstDayOfWeek(
  override?: FirstDayOfWeek,
): FirstDayOfWeek | undefined {
  const intl = useIntl()

  return override ?? (getStartOfWeek(intl.locale) === 0 ? 'sun' : undefined)
}

type AnyCalendarState = NonNullable<
  | React.ContextType<typeof CalendarStateContext>
  | React.ContextType<typeof RangeCalendarStateContext>
>

/**
 * Reads the calendar state from React Aria's context, so a component works
 * inside both Calendar and RangeCalendar
 */
function useAnyCalendarState(): AnyCalendarState | null {
  const calendarState = useContext(CalendarStateContext)
  const rangeCalendarState = useContext(RangeCalendarStateContext)

  return calendarState ?? rangeCalendarState
}

/**
 * The month navigation header shared between the day, week and range
 * calendars. When condensed, the previous/next buttons page one week at a
 * time (by moving the focused date) instead of one month, since the grid only
 * shows a single week
 */
export function CalendarHeader({
  condensed = false,
}: {
  condensed?: boolean
}): JSX.Element {
  const intl = useIntl()
  const { formatMonthAndYearLong, formatYearAndMonth } = useDateFormatters()
  const state = useAnyCalendarState()

  if (!state) {
    throw new Error(
      'CalendarHeader must be rendered inside a Calendar or RangeCalendar',
    )
  }

  const focusedDate = state.focusedDate
  // Use a date in the middle of the month to avoid timezone related shifts
  // when formatting, mirroring the legacy DatePicker implementation
  const month = new Date(focusedDate.year, focusedDate.month - 1, 15)

  const focusPrevious = () => {
    if (condensed) {
      state.setFocusedDate(state.focusedDate.subtract({ weeks: 1 }))
    } else {
      state.focusPreviousPage()
    }
  }

  const focusNext = () => {
    if (condensed) {
      state.setFocusedDate(state.focusedDate.add({ weeks: 1 }))
    } else {
      state.focusNextPage()
    }
  }

  // Disable the paging buttons once the adjacent month falls entirely outside
  // minValue/maxValue. These helpers reflect the month visible range, so they
  // only apply to the (month-paging) non-condensed calendar; condensed week
  // paging is left always-enabled
  const isPreviousDisabled = !condensed && state.isPreviousVisibleRangeInvalid()
  const isNextDisabled = !condensed && state.isNextVisibleRangeInvalid()

  return (
    <div className="flex items-center justify-between">
      {/* Decorative: React Aria's CalendarGrid announces the month to
          assistive technology (with a live region on navigation), so this
          visible heading is hidden to avoid a duplicate announcement */}
      <time
        aria-hidden="true"
        className="text-sm font-medium leading-4"
        dateTime={formatYearAndMonth(month)}
      >
        {formatMonthAndYearLong(month)}
      </time>
      <div className="flex items-center justify-between w-16">
        <IconButton
          aria-label={intl.formatMessage({ id: 'DatePicker.previous' })}
          disabled={isPreviousDisabled}
          onClick={focusPrevious}
        >
          <ChevronLeft />
        </IconButton>
        <IconButton
          aria-label={intl.formatMessage({ id: 'DatePicker.next' })}
          disabled={isNextDisabled}
          onClick={focusNext}
        >
          <ChevronRight />
        </IconButton>
      </div>
    </div>
  )
}

/**
 * A visually hidden live region that announces the week containing the
 * focused date (e.g. "Week of January 12th, 2020") as the user navigates in
 * week mode. React Aria labels each cell with its own date only, so without
 * this a screen reader user never hears which week their keystroke landed on.
 * The text only changes when focus crosses into a different week, so moving
 * between days of the same week stays silent
 */
export function WeekAnnouncement({
  firstDayOfWeek,
}: {
  firstDayOfWeek?: FirstDayOfWeek
}): JSX.Element {
  const intl = useIntl()
  const { formatDateLong } = useDateFormatters()
  const state = useAnyCalendarState()

  if (!state) {
    throw new Error(
      'WeekAnnouncement must be rendered inside a Calendar or RangeCalendar',
    )
  }

  const weekStart = startOfWeek(state.focusedDate, intl.locale, firstDayOfWeek)

  return (
    <div aria-atomic="true" aria-live="polite" className="sr-only">
      {intl.formatMessage(
        { id: 'DatePicker.week_of' },
        {
          // Constructed in local time purely for formatting, mirroring the
          // month heading above
          date: formatDateLong(
            new Date(weekStart.year, weekStart.month - 1, weekStart.day),
          ),
        },
      )}
    </div>
  )
}

interface CalendarCellsProps {
  /**
   * When true, days outside the current month are not dimmed since a
   * condensed calendar only ever renders a single week
   */
  condensed?: boolean
  mode: CalendarMode
  /**
   * The currently selected week, only used to highlight the entire row in
   * week mode
   */
  selectedWeek?: SelectedWeek | null
  timezone: string
}

/**
 * React Aria's CalendarGridBody always renders every week of the visible
 * month, so a condensed calendar renders its own single row containing only
 * the dates within the currently visible week
 */
function CondensedGridBody({
  children,
}: {
  children: (date: CalendarDate) => JSX.Element
}): JSX.Element {
  const state = useAnyCalendarState()

  if (!state) {
    throw new Error(
      'CondensedGridBody must be rendered inside a Calendar or RangeCalendar',
    )
  }

  return (
    <tbody>
      <tr>
        {/* Key off focusedDate (not visibleRange.start) so the row shows the
            selected/focused week and stays aligned to firstDayOfWeek */}
        {state.getDatesInWeek(0, state.focusedDate).map((date, index) =>
          date ? (
            <React.Fragment key={date.toString()}>
              {children(date)}
            </React.Fragment>
          ) : (
            // eslint-disable-next-line react/no-array-index-key
            <td key={index} />
          ),
        )}
      </tr>
    </tbody>
  )
}

/**
 * The weekday header row and date cells shared between the day, week and
 * range calendars
 */
export function CalendarCells({
  condensed = false,
  mode,
  selectedWeek = null,
  timezone,
}: CalendarCellsProps): JSX.Element {
  const intl = useIntl()
  const state = useAnyCalendarState()
  // Selecting a day from an adjacent month happens in two steps: the click
  // moves focus, paging the calendar to that day's month, and this effect
  // completes the selection once the day is inside the visible range.
  // react-stately validates selections against the visible range, so
  // selecting straight from the click would be silently dropped
  const pendingOutsideDay = useRef<CalendarDate | null>(null)
  // The adjacent-month day the pointer is currently over while the user is
  // picking the end of a range. React Aria's own hover preview stops at the
  // month boundary because those cells are inert, so the preview range is
  // derived from this manually. Extending it through setFocusedDate instead
  // would page the calendar to the hovered day's month
  const [previewDate, setPreviewDate] = useState<CalendarDate | null>(null)

  // The anchor is the fixed end of an in-progress range selection; it is
  // null once the range completes or is reset
  const anchorDate =
    mode === 'range' && state && 'anchorDate' in state ? state.anchorDate : null
  const focusedDate = state?.focusedDate ?? null

  // The preview is sticky like react-aria's own: it is never cleared on
  // mouseout (the pointer constantly crosses the gaps between cells, and
  // retracting there made the highlight flicker back to the last in-month
  // day). Instead it resets whenever something else takes over: hovering or
  // keyboard-navigating an in-month day moves the focused date, and
  // completing or resetting the selection clears the anchor
  useEffect(() => {
    setPreviewDate(null)
  }, [anchorDate, focusedDate])

  useEffect(() => {
    const date = pendingOutsideDay.current

    if (
      state &&
      date &&
      date.compare(state.visibleRange.start) >= 0 &&
      date.compare(state.visibleRange.end) <= 0
    ) {
      pendingOutsideDay.current = null
      state.selectDate(date)
    }
  })

  if (!state) {
    throw new Error(
      'CalendarCells must be rendered inside a Calendar or RangeCalendar',
    )
  }

  const week = mode === 'week'
  const dayOrRange = mode === 'day' || mode === 'range'

  const inSelectedWeek = (date: CalendarDate): boolean =>
    selectedWeek !== null &&
    date.compare(selectedWeek.start) >= 0 &&
    date.compare(selectedWeek.end) <= 0

  const isOutsideDay = (date: CalendarDate): boolean =>
    date.compare(state.visibleRange.start) < 0 ||
    date.compare(state.visibleRange.end) > 0

  // React Aria hard-disables the adjacent-month days that pad the grid's
  // first and last weeks. Per design they stay selectable as long as they
  // satisfy the calendar's own constraints (bounds, availability)
  const isSelectableOutsideDay = (date: CalendarDate): boolean =>
    isOutsideDay(date) &&
    !state.isDisabled &&
    !state.isReadOnly &&
    !state.isInvalid(date) &&
    !state.isCellUnavailable(date)

  const selectOutsideDay = (date: CalendarDate): void => {
    pendingOutsideDay.current = date
    state.setFocusedDate(date)
  }

  // React Aria never reports the adjacent-month padding days as selected
  // because they sit outside the visible range, which visually broke a range
  // at the month boundary. Selection state is computed manually instead: from
  // the hovered adjacent-month day while a selection is in progress, and from
  // the highlighted range (which also covers react-aria's own in-progress
  // preview) otherwise, so the highlight behaves like the legacy DatePicker
  const rangeState =
    mode === 'range' && 'highlightedRange' in state ? state : null
  const previewRange =
    anchorDate !== null && previewDate !== null
      ? anchorDate.compare(previewDate) <= 0
        ? { start: anchorDate, end: previewDate }
        : { start: previewDate, end: anchorDate }
      : null
  const manualRange = previewRange ?? rangeState?.highlightedRange ?? null

  const renderCell = (date: CalendarDate) => {
    const selectableOutsideDay = isSelectableOutsideDay(date)

    // The disabled/invalid/unavailable checks mirror the ones react-stately
    // applies to in-month days
    const manuallySelected =
      manualRange !== null &&
      !state.isDisabled &&
      !state.isInvalid(date) &&
      !state.isCellUnavailable(date) &&
      date.compare(manualRange.start) >= 0 &&
      date.compare(manualRange.end) <= 0
    const manualSelectionStart =
      manuallySelected &&
      manualRange !== null &&
      date.compare(manualRange.start) === 0
    const manualSelectionEnd =
      manuallySelected &&
      manualRange !== null &&
      date.compare(manualRange.end) === 0

    return (
      <CalendarCell
        className={({
          isDisabled,
          isOutsideMonth,
          isSelected,
          isSelectionEnd,
          isSelectionStart,
          isUnavailable,
        }) => {
          const selectedWeekDay = week && inSelectedWeek(date)
          // While the pointer previews across the month boundary, react-aria's
          // own flags lag behind at the last in-month day it focused, so the
          // manual state replaces them rather than merging with them
          const selected = previewRange
            ? manuallySelected
            : isSelected || manuallySelected
          const selectionStart = previewRange
            ? manualSelectionStart
            : isSelectionStart || manualSelectionStart
          const selectionEnd = previewRange
            ? manualSelectionEnd
            : isSelectionEnd || manualSelectionEnd
          // The solid filled day: the selected day itself, or either end of a
          // range, including when that end pads an adjacent month
          const solidDay =
            selected && (mode === 'day' || selectionStart || selectionEnd)
          // Locale-aware: weekend days vary by locale (e.g. Fri/Sat in some
          // regions) and this respects the calendar system rather than
          // assuming a Gregorian Sat/Sun
          const weekend = isWeekend(date, intl.locale)

          return clsx(
            'flex justify-center outline-none text-center',
            dayOrRange && 'group',
            // Text colors
            dayOrRange && solidDay ? 'text-white-100' : null,
            dayOrRange && !isSelected && !weekend && !isOutsideMonth
              ? 'text-black-90'
              : null,
            dayOrRange && !solidDay && isOutsideMonth && !condensed
              ? 'text-black-60'
              : null,
            dayOrRange && !solidDay && !isSelected && weekend
              ? 'text-black-60'
              : null,
            week && weekend && !selectedWeekDay ? 'text-black-60' : null,
            // Range selection highlight, including the hover preview while
            // the user is picking the end of the range. The cell is wider
            // than the solid selected circle, so the endpoints paint only
            // the inner half of the band; a full-width band would peek out
            // from behind the circle, which the legacy DatePicker (whose
            // cells matched the circle width) never showed
            mode === 'range' && selected && !selectionStart && !selectionEnd
              ? 'bg-primary-20'
              : null,
            // At the row edge the half band has no neighbouring cell to
            // connect to, so it is dropped entirely rather than left
            // dangling beside the circle
            mode === 'range' && selectionStart && !selectionEnd
              ? '[td:not(:last-child)_&]:[background-image:linear-gradient(to_right,transparent_50%,var(--color-primary-20)_50%)]'
              : null,
            mode === 'range' && selectionEnd && !selectionStart
              ? '[td:not(:first-child)_&]:[background-image:linear-gradient(to_left,transparent_50%,var(--color-primary-20)_50%)]'
              : null,
            mode === 'range' && selected
              ? '[td:first-child_&]:rounded-l-full [td:last-child_&]:rounded-r-full'
              : null,
            // Week mode highlights the entire row
            week &&
              '[td:first-child_&]:rounded-l-full [td:last-child_&]:rounded-r-full',
            week && selectedWeekDay ? 'bg-primary-main text-white-100' : null,
            // Preview the week that would be selected: on the hovered row for
            // pointer users, and on the row containing the keyboard-focused
            // date for keyboard users. Driven by the native :focus-visible
            // pseudo-class rather than React Aria's data-focus-visible
            // attribute, which is removed a frame before focus moves and made
            // the highlight flicker on every keystroke. Firefox does not
            // carry keyboard modality into the programmatic focus() React
            // Aria uses to move between cells, so :focus-visible never
            // matches there — the data-focus-visible + :focus fallback
            // restores the highlight for it
            week && !selectedWeekDay
              ? '[tr:hover_&]:bg-primary-20 [tr:active_&]:bg-primary-20 [tr:has(:focus-visible)_&]:bg-primary-20 [tr:has([data-focus-visible]:focus)_&]:bg-primary-20'
              : null,
            (isDisabled && !selectableOutsideDay) || isUnavailable
              ? 'cursor-not-allowed opacity-60'
              : 'cursor-pointer',
          )
        }}
        date={date}
      >
        {({ formattedDate, isSelected, isSelectionEnd, isSelectionStart }) => {
          const rangeSelected = previewRange
            ? manuallySelected
            : isSelected || manuallySelected
          const rangeEndpoint = previewRange
            ? manualSelectionStart || manualSelectionEnd
            : isSelectionStart ||
              isSelectionEnd ||
              manualSelectionStart ||
              manualSelectionEnd
          const selectedDay =
            (mode === 'day' && isSelected) ||
            (mode === 'range' && rangeSelected && rangeEndpoint)
          const selectedWeekDay = week && inSelectedWeek(date)
          const today = isToday(date, timezone)

          return (
            <time
              className={clsx(
                'flex items-center justify-center w-8 h-8 text-sm leading-4 rounded-full',
                // Keyboard focus indicator, driven by the parent cell's
                // native :focus-visible so the ring moves atomically with DOM
                // focus. React Aria's isFocusVisible render prop clears one
                // render before focus actually moves to the next cell, which
                // painted a ring-less frame on every keystroke (and briefly
                // ringed the wrong cell when crossing months). Firefox does
                // not carry keyboard modality into the programmatic focus()
                // React Aria uses to move between cells, so :focus-visible
                // never matches there — the data-focus-visible + :focus
                // fallback restores the ring for it
                '[:focus-visible>&]:ring [[data-focus-visible]:focus>&]:ring',
                // Hover and focus tints are skipped on the selected day so
                // the solid selected fill shows immediately after clicking,
                // while the cell is still hovered and focused
                dayOrRange &&
                  !selectedDay &&
                  'group-active:bg-primary-20 group-focus:bg-primary-20 group-hover:bg-primary-20',
                selectedDay ? 'bg-primary-main' : null,
                today && !selectedDay && dayOrRange ? 'bg-black-10' : null,
                today && week && !selectedWeekDay
                  ? 'bg-black-10 group-active:bg-primary-20'
                  : null,
                today && week && selectedWeekDay ? 'bg-primary-dark' : null,
              )}
              dateTime={date.toString()}
              // React Aria renders the cell inert (no press handling) because
              // the day is outside the visible month, so the click is handled
              // here instead
              {...(selectableOutsideDay && {
                onClick: () => selectOutsideDay(date),
              })}
              {...(mode === 'range' &&
                anchorDate !== null && {
                  // Hovering an adjacent-month day extends the preview to
                  // it; hovering an in-month day hands the preview back to
                  // react-aria (whose focused-date update also clears it via
                  // the effect above, covering hovers that land on the cell
                  // padding around this element)
                  onMouseOver: () =>
                    setPreviewDate(selectableOutsideDay ? date : null),
                })}
            >
              {formattedDate}
            </time>
          )
        }}
      </CalendarCell>
    )
  }

  return (
    <CalendarGrid
      className="w-full mt-4 table-fixed border-separate border-spacing-y-2"
      weekdayStyle="short"
    >
      <CalendarGridHeader>
        {(day) => (
          <CalendarHeaderCell className="text-xs font-normal leading-4 text-center text-black-90">
            {/* Use the locale's short weekday abbreviation as-is; truncating
                to two characters collided in some locales (e.g. pt/es where
                several days share the first two letters) */}
            {day}
          </CalendarHeaderCell>
        )}
      </CalendarGridHeader>
      {condensed ? (
        <CondensedGridBody>{renderCell}</CondensedGridBody>
      ) : (
        <CalendarGridBody>{renderCell}</CalendarGridBody>
      )}
    </CalendarGrid>
  )
}
