import type { CalendarDate } from '@internationalized/date'
import {
  endOfWeek,
  startOfWeek,
  Time,
  toCalendarDateTime,
  today,
} from '@internationalized/date'
import clsx from 'clsx'
import React, { useMemo, useState } from 'react'
import {
  Calendar as AriaCalendar,
  RangeCalendar as AriaRangeCalendar,
  I18nProvider,
} from 'react-aria-components'
import type {
  CalendarProps as AriaCalendarProps,
  RangeCalendarProps as AriaRangeCalendarProps,
} from 'react-aria-components'
import { useIntl } from 'react-intl'
import {
  calendarContainerClasses,
  CalendarCells,
  CalendarHeader,
  useFirstDayOfWeek,
  WeekAnnouncement,
} from './CalendarBase'
import {
  calendarConstraints,
  resolveTimezone,
  toCalendarDate,
  toNativeDate,
} from './dates'
import type { FirstDayOfWeek, SelectedWeek } from './types'

interface CalendarBaseProps {
  /**
   * An accessible label for the calendar, announced to assistive technology
   */
  'aria-label'?: string
  /**
   * Whether the calendar grid should receive focus when it first renders
   * @default false
   */
  autoFocus?: boolean
  /**
   * Additional classes applied to the calendar container
   */
  className?: string
  /**
   * When true, displays a condensed calendar view showing only one week
   * instead of the full month
   * @default false
   */
  condensed?: boolean
  /**
   * The day that starts the week in the calendar grid, and that weeks snap
   * to in week mode. Defaults to the locale's first day of the week
   */
  firstDayOfWeek?: FirstDayOfWeek
  /**
   * The id attribute of the calendar element
   */
  id?: string
  /**
   * Callback that is called for each visible date. Returning true marks the
   * date as unavailable so it cannot be selected
   */
  isDateUnavailable?: (date: Date) => boolean
  /**
   * If true, the entire calendar is disabled and no date can be selected
   * @default false
   */
  isDisabled?: boolean
  /**
   * The latest date that a user may select
   */
  maxDate?: Date
  /**
   * The earliest date that a user may select
   */
  minDate?: Date
  /**
   * IANA timezone identifier (e.g. 'America/New_York') used to determine
   * today's date and the dates emitted through onChange.
   * Defaults to the user's local timezone if not provided or invalid
   */
  timezone?: string
}

export interface CalendarDayProps extends CalendarBaseProps {
  /**
   * The initially selected date (uncontrolled)
   */
  defaultValue?: Date | null
  /**
   * Selection mode for the calendar
   * @default 'day'
   */
  mode?: 'day'
  /**
   * Callback invoked with the selected date when it changes
   */
  onChange?: (date: Date) => void
  /**
   * The selected date (controlled)
   */
  value?: Date | null
}

export interface CalendarWeekProps extends CalendarBaseProps {
  /**
   * The initially selected week (uncontrolled). A single date selects the
   * week containing it
   */
  defaultValue?: Date | [Date, Date] | null
  mode: 'week'
  /**
   * Callback invoked with the start and end dates of the selected week
   */
  onChange?: (range: [Date, Date]) => void
  /**
   * The selected week (controlled). A single date selects the week
   * containing it
   */
  value?: Date | [Date, Date] | null
}

export interface CalendarRangeProps extends CalendarBaseProps {
  /**
   * Whether a range may span dates marked unavailable by `isDateUnavailable`.
   * When false (the default) the range is clamped so it cannot cross an
   * unavailable date; when true the range may span them and the unavailable
   * dates within it simply stay unselectable
   * @default false
   */
  allowsNonContiguousRanges?: boolean
  /**
   * The initially selected date range (uncontrolled)
   */
  defaultValue?: [Date, Date] | null
  mode: 'range'
  /**
   * Callback invoked with the start and end dates of the selected range
   */
  onChange?: (range: [Date, Date]) => void
  /**
   * The selected date range (controlled)
   */
  value?: [Date, Date] | null
}

export type CalendarProps =
  | CalendarDayProps
  | CalendarRangeProps
  | CalendarWeekProps

const END_OF_DAY = new Time(23, 59, 59, 999)

function firstDate(value: Date | [Date, Date] | null): Date | null {
  return Array.isArray(value) ? value[0] : value
}

function Calendar(props: CalendarProps): JSX.Element {
  const {
    'aria-label': ariaLabel,
    autoFocus = false,
    className,
    condensed = false,
    firstDayOfWeek: firstDayOfWeekProp,
    id,
    isDateUnavailable,
    isDisabled = false,
    maxDate,
    minDate,
    mode = 'day',
    timezone,
  } = props
  const intl = useIntl()
  const firstDayOfWeek = useFirstDayOfWeek(firstDayOfWeekProp)
  const resolvedTimezone = useMemo(() => resolveTimezone(timezone), [timezone])

  const snapToWeek = (date: CalendarDate): SelectedWeek => ({
    end: endOfWeek(date, intl.locale, firstDayOfWeek),
    start: startOfWeek(date, intl.locale, firstDayOfWeek),
  })

  const [
    internalWeekAnchor,
    setInternalWeekAnchor,
  ] = useState<CalendarDate | null>(() => {
    if (mode !== 'week') {
      return null
    }

    const initial = firstDate((props as CalendarWeekProps).defaultValue ?? null)

    return initial ? toCalendarDate(initial, resolvedTimezone) : null
  })

  const constraints = calendarConstraints(
    { isDateUnavailable, maxDate, minDate },
    resolvedTimezone,
  )
  // The bounds are read back out for week-mode clamping below (clampWeekValue)
  const { maxValue, minValue } = constraints

  const sharedProps = {
    autoFocus,
    className: clsx(calendarContainerClasses, className),
    // The month stays the visible duration even when condensed; the condensed
    // grid renders a single week itself (CondensedGridBody) and the header
    // pages by week. A one-week visibleDuration cannot honor firstDayOfWeek
    // (react-stately's range alignment ignores it), which misaligns the row
    firstDayOfWeek,
    isDisabled,
    ...(ariaLabel && { 'aria-label': ariaLabel }),
    ...(id && { id }),
    ...constraints,
  }

  if (mode === 'range') {
    const {
      allowsNonContiguousRanges,
      defaultValue,
      onChange,
      value,
    } = props as CalendarRangeProps

    const rangeProps: AriaRangeCalendarProps<CalendarDate> = {
      ...sharedProps,
      ...(allowsNonContiguousRanges && { allowsNonContiguousRanges }),
      ...(defaultValue !== undefined && {
        defaultValue: defaultValue && {
          end: toCalendarDate(defaultValue[1], resolvedTimezone),
          start: toCalendarDate(defaultValue[0], resolvedTimezone),
        },
      }),
      ...(value !== undefined && {
        value: value && {
          end: toCalendarDate(value[1], resolvedTimezone),
          start: toCalendarDate(value[0], resolvedTimezone),
        },
      }),
      onChange: (range) =>
        onChange?.([
          toNativeDate(range.start, resolvedTimezone),
          toNativeDate(range.end, resolvedTimezone),
        ]),
      ...(!value &&
        !defaultValue && { defaultFocusedValue: today(resolvedTimezone) }),
    }

    return (
      <I18nProvider locale={intl.locale}>
        <AriaRangeCalendar {...rangeProps}>
          <CalendarHeader condensed={condensed} />
          <CalendarCells
            condensed={condensed}
            mode="range"
            timezone={resolvedTimezone}
          />
        </AriaRangeCalendar>
      </I18nProvider>
    )
  }

  if (mode === 'week') {
    const { onChange, value } = props as CalendarWeekProps

    const controlled = value !== undefined
    const anchorDate = controlled
      ? (() => {
          const date = firstDate(value ?? null)

          return date ? toCalendarDate(date, resolvedTimezone) : null
        })()
      : internalWeekAnchor
    const selectedWeek = anchorDate ? snapToWeek(anchorDate) : null

    // The week start can fall before minValue (or after maxValue) when a bound
    // lands mid-week; clamp the value handed to the calendar into range so the
    // whole calendar is not marked invalid. The full-week highlight comes from
    // CalendarCells' selectedWeek, independent of this single value
    const clampWeekValue = (date: CalendarDate): CalendarDate => {
      if (minValue && date.compare(minValue) < 0) {
        return minValue
      }

      if (maxValue && date.compare(maxValue) > 0) {
        return maxValue
      }

      return date
    }

    const weekProps: AriaCalendarProps<CalendarDate> = {
      ...sharedProps,
      // React Aria appends the visible month, so assistive technology hears
      // "Select a week, January 2020" and knows a press picks the whole week
      'aria-label':
        ariaLabel ?? intl.formatMessage({ id: 'DatePicker.select_week' }),
      value: selectedWeek ? clampWeekValue(selectedWeek.start) : null,
      onChange: (date) => {
        const week = snapToWeek(date)

        if (!controlled) {
          setInternalWeekAnchor(week.start)
        }

        onChange?.([
          toNativeDate(week.start, resolvedTimezone),
          toCalendarDateTime(week.end, END_OF_DAY).toDate(resolvedTimezone),
        ])
      },
      ...(!selectedWeek && { defaultFocusedValue: today(resolvedTimezone) }),
    }

    return (
      <I18nProvider locale={intl.locale}>
        <AriaCalendar {...weekProps}>
          <CalendarHeader condensed={condensed} />
          <CalendarCells
            condensed={condensed}
            mode="week"
            selectedWeek={selectedWeek}
            timezone={resolvedTimezone}
          />
          <WeekAnnouncement firstDayOfWeek={firstDayOfWeek} />
        </AriaCalendar>
      </I18nProvider>
    )
  }

  const { defaultValue, onChange, value } = props as CalendarDayProps

  const dayProps: AriaCalendarProps<CalendarDate> = {
    ...sharedProps,
    ...(defaultValue !== undefined && {
      defaultValue:
        defaultValue && toCalendarDate(defaultValue, resolvedTimezone),
    }),
    ...(value !== undefined && {
      value: value && toCalendarDate(value, resolvedTimezone),
    }),
    onChange: (date) => onChange?.(toNativeDate(date, resolvedTimezone)),
    ...(!value &&
      !defaultValue && { defaultFocusedValue: today(resolvedTimezone) }),
  }

  return (
    <I18nProvider locale={intl.locale}>
      <AriaCalendar {...dayProps}>
        <CalendarHeader condensed={condensed} />
        <CalendarCells
          condensed={condensed}
          mode="day"
          timezone={resolvedTimezone}
        />
      </AriaCalendar>
    </I18nProvider>
  )
}

export default Calendar
