/* eslint-disable react/forbid-component-props */
import clsx from 'clsx'
import React, { useCallback, useEffect, useState } from 'react'
import type { ReactNode } from 'react'
import { Popover as AriaPopover } from 'react-aria-components'
import type { PopoverProps as AriaPopoverProps } from 'react-aria-components'

export type PopoverPlacement = AriaPopoverProps['placement'] | 'center'
const CENTER_PLACEMENT_EDGE_THRESHOLD = 20 // pixels from the edge of the viewport

export interface PopoverProps {
  /**
   * Defines a string value that labels the popover
   */
  'aria-label'?: string
  /**
   * Identifies the element (or elements) that labels the popover
   */
  'aria-labelledby'?: string
  /**
   * Identifies the element (or elements) that describes the popover
   */
  'aria-describedby'?: string
  /**
   * The content to display inside the popover
   */
  children: ReactNode
  /**
   * Whether the popover is non-modal, allowing elements outside of it to be
   * interacted with while it is open
   */
  isNonModal?: boolean
  /**
   * Whether the popover is open. When omitted it defaults to closed, unless
   * `contextDriven` is set — in which case the open state comes from the
   * surrounding React Aria trigger context
   */
  isOpen?: boolean
  /**
   * Defer the open state and trigger anchoring to a surrounding React Aria
   * trigger context (e.g. DatePicker or DialogTrigger) rather than managing
   * them here. Leave this off (the default) for a standalone popover so it
   * stays closed until `isOpen` is set and never inherits an unrelated
   * overlay context such as a Drawer's
   */
  contextDriven?: boolean
  /**
   * The distance in pixels between the trigger element and the popover
   * @default 8
   */
  offset?: number
  /**
   * Callback fired when the popover open state changes
   */
  onOpenChange?: (isOpen: boolean) => void
  /**
   * The placement of the popover relative to the trigger element
   * @default 'bottom'
   */
  placement?: PopoverPlacement
  /**
   * Reference to the trigger element that opens the popover
   */
  triggerRef?: React.RefObject<HTMLElement>
}

const Popover = React.forwardRef<HTMLDivElement, PopoverProps>(function Popover(
  {
    'aria-label': ariaLabel,
    'aria-labelledby': ariaLabelledby,
    'aria-describedby': ariaDescribedby,
    children,
    contextDriven = false,
    isNonModal,
    isOpen,
    offset = 8,
    onOpenChange,
    placement = 'bottom',
    triggerRef,
  },
  forwardedRef,
): JSX.Element {
  const popoverRef = React.useRef<HTMLDivElement | null>(null)
  // A standalone popover defaults to closed so it never inherits an unrelated
  // overlay context (e.g. a Drawer's) and renders with no triggerRef; a
  // context-driven popover forwards nothing and defers to that context
  const resolvedIsOpen = contextDriven ? undefined : isOpen ?? false

  // Stable across renders so React does not detach and reattach the popover
  // node every time the parent re-renders
  const setRefs = useCallback(
    (node: HTMLDivElement | null) => {
      popoverRef.current = node

      if (typeof forwardedRef === 'function') {
        forwardedRef(node)
      } else if (forwardedRef) {
        forwardedRef.current = node
      }
    },
    [forwardedRef],
  )

  const [isNearEdge, setIsNearEdge] = useState(false)
  const isCenterPlacement = placement === 'center'

  useEffect(
    function useCenterPlacementOffset() {
      const popover = popoverRef.current
      if (!popover || !isCenterPlacement) return

      const updateCenterOffset = () => {
        const trigger = triggerRef?.current
        const popoverStyles = getComputedStyle(popover)
        const popoverHeight = popoverStyles
          .getPropertyValue('--trigger-anchor-point')
          .replace(/px/g, '')
          .split(' ')[1]

        if (trigger && popoverHeight) {
          const triggerStyles = getComputedStyle(trigger)
          const borderWidth = parseFloat(triggerStyles.borderWidth) || 0
          const totalHeight = trigger.clientHeight + borderWidth * 2

          popover.style.setProperty(
            '--center-offset',
            Number(popoverHeight) / 2 + totalHeight / 2 + offset + 'px',
          )
        }
      }

      if (isOpen) {
        requestAnimationFrame(updateCenterOffset)
      }
    },
    [isCenterPlacement, isOpen, offset, triggerRef],
  )

  useEffect(
    function useEdgeProximityDetection() {
      const trigger = triggerRef?.current
      if (!trigger || !isCenterPlacement || !isOpen) {
        return
      }

      const checkEdgeProximity = () => {
        const rect = trigger.getBoundingClientRect()
        const threshold = CENTER_PLACEMENT_EDGE_THRESHOLD

        const nearTop = rect.top < threshold
        const nearBottom = window.innerHeight - rect.bottom < threshold
        const nearLeft = rect.left < threshold
        const nearRight = window.innerWidth - rect.right < threshold

        const isNear = nearTop || nearBottom || nearLeft || nearRight
        setIsNearEdge(isNear)
      }

      requestAnimationFrame(() => {
        requestAnimationFrame(checkEdgeProximity)
      })

      let resizeTimeout: ReturnType<typeof setTimeout>
      const debouncedCheckEdgeProximity = () => {
        clearTimeout(resizeTimeout)
        resizeTimeout = setTimeout(checkEdgeProximity, 100)
      }

      window.addEventListener('resize', debouncedCheckEdgeProximity)

      return () => {
        window.removeEventListener('resize', debouncedCheckEdgeProximity)
        clearTimeout(resizeTimeout)
        // reset after animation completes
        setTimeout(() => {
          setIsNearEdge(false)
        }, 300)
      }
    },
    [isCenterPlacement, isOpen, triggerRef],
  )

  // Open state, trigger, and modality props are only forwarded when provided
  // so a surrounding React Aria trigger context stays in control otherwise
  return (
    <AriaPopover
      aria-describedby={ariaDescribedby}
      aria-label={ariaLabel}
      aria-labelledby={ariaLabelledby}
      className={clsx(
        'react-aria-Popover focus-visible:ring',
        isCenterPlacement && !isNearEdge && 'center-placement',
      )}
      offset={offset}
      placement={isCenterPlacement ? 'top' : placement}
      ref={setRefs}
      {...(isNonModal !== undefined && { isNonModal })}
      {...(resolvedIsOpen !== undefined && { isOpen: resolvedIsOpen })}
      {...(onOpenChange && { onOpenChange })}
      {...(triggerRef && { triggerRef })}
    >
      {children}
    </AriaPopover>
  )
})

export default Popover
